609	+import { SITE_OWNER } from '@wolsok/shared-legal';
610	+import { BlogPost, blogPostPath } from './blog-post';
611	+
612	+/**
613	+ * The `BlogPosting` schema.org data of a post, for search engines: in
614	+ * English, the language the pages are prerendered in.
615	+ */
616	+export function blogPostingJsonLd(post: BlogPost, siteUrl: string): string {
617	+  const url = siteUrl + blogPostPath(post);
618	+  return JSON.stringify({
619	+    '@context': 'https://schema.org',
620	+    '@type': 'BlogPosting',
621	+    headline: post.title.en,
622	+    description: post.summary.en,
623	+    datePublished: post.published,
624	+    inLanguage: ['en', 'de'],
625	+    url,
626	+    mainEntityOfPage: url,
627	+    author: { '@type': 'Person', name: SITE_OWNER.name, url: siteUrl },
628	+  });
629	+}
