636	+import { Type } from '@angular/core';
637	+import { Localized } from '../i18n/language';
638	+
639	+/** An article of the blog, as the index, the routes and the JSON-LD see it. */
640	+export interface BlogPost {
641	+  /** The last segment of its URL, `/blog/<slug>`. */
642	+  readonly slug: string;
643	+  /** The day it was published, `YYYY-MM-DD`. */
644	+  readonly published: string;
645	+  readonly title: Localized;
646	+  /** One or two sentences: the index's teaser and the page's description. */
647	+  readonly summary: Localized;
648	+  /** The article's page, loaded only when it is opened. */
649	+  readonly loadComponent: () => Promise<Type<unknown>>;
650	+}
651	+
652	+/** Where a post lives on the site, without the origin. */
653	+export function blogPostPath(post: BlogPost): string {
654	+  return `/blog/${post.slug}`;
655	+}
656	+
657	+/** The day a post was published, written out in a locale (`20 November 2026`). */
658	+export function publishedOn(post: BlogPost, locale: string): string {
659	+  return new Date(`${post.published}T00:00:00Z`).toLocaleDateString(locale, {
660	+    dateStyle: 'long',
661	+    timeZone: 'UTC',
662	+  });
663	+}
